local PendantMaker = {}
local PRODUCTS = {
    simple_bronze_pendant = { name = "Preprost bronast obesek", bronzeCost = 1, leatherCost = 1, time = 3, cost = 40, beauty = 20, prestige = 2, happiness = 1, description = "Preprost bronast obesek za okras." },
    silver_chain_pendant = { name = "Srebrnoverižni obesek", silverCost = 1, bronzeCost = 1, leatherCost = 1, time = 5, cost = 130, beauty = 35, prestige = 6, happiness = 2, description = "Srebrnoverižni obesek za trgovce." },
    gold_chain_pendant = { name = "Zlato verižni obesek", goldCost = 1, silverCost = 1, bronzeCost = 1, leatherCost = 1, time = 8, cost = 320, beauty = 50, prestige = 12, happiness = 2, description = "Zlato verižni obesek za plemiče." },
    jewel_centered_pendant = { name = "Draguljnokrožni obesek", goldCost = 1, silverCost = 1, bronzeCost = 1, leatherCost = 1, jewelCost = 1, time = 12, cost = 780, beauty = 65, prestige = 22, happiness = 3, description = "Obesek z draguljem za visoke plemiče." },
    pearl_drop_pendant = { name = "Bisernovesljajoči obesek", goldCost = 2, silverCost = 1, bronzeCost = 1, leatherCost = 1, jewelCost = 1, pearlCost = 1, time = 16, cost = 1700, beauty = 80, prestige = 35, happiness = 5, description = "Obesek z bisernim vešanjem za visoko plemstvo." },
    royal_grand_pendant = { name = "Kraljevski veliki obesek", goldCost = 3, silverCost = 2, bronzeCost = 1, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3800, beauty = 95, prestige = 62, happiness = 12, description = "Veliki kraljevski obesek z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    pendant_workshop = { name = "Obesna delavnica", cost = { gold = 220, wood = 100, stone = 120, bronze = 6 }, upkeep = 5, qualityBonus = 5 },
    jewelry_loft = { name = "Nakitna podstrešje", cost = { gold = 880, wood = 240, stone = 240, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_jeweler_atelier = { name = "Mojstrski nakitni atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_jewelry_palace = { name = "Kraljevska nakitna palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
PendantMaker.bronzeStock = 12; PendantMaker.leatherStock = 12; PendantMaker.silverStock = 8; PendantMaker.goldStock = 6; PendantMaker.jewelStock = 4; PendantMaker.pearlStock = 4
PendantMaker.productStock = {}; PendantMaker.buildings = {}; PendantMaker.maker = nil; PendantMaker.activeMaking = {}; PendantMaker.totalProducts = 0; PendantMaker.dayTimer = 0
function PendantMaker.init() PendantMaker.bronzeStock=12; PendantMaker.leatherStock=12; PendantMaker.silverStock=8; PendantMaker.goldStock=6; PendantMaker.jewelStock=4; PendantMaker.pearlStock=4; PendantMaker.productStock={}; PendantMaker.buildings={}; PendantMaker.maker=nil; PendantMaker.activeMaking={}; PendantMaker.totalProducts=0; PendantMaker.dayTimer=0; print("[PendantMaker] Royal Pendant Maker System initialized (6 products, 4 buildings)") end
function PendantMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PendantMaker.maker={name=n or ("Obeskar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obeskar najet: %s (spretnost: %d)",PendantMaker.maker.name,s),"success") end; return true end
function PendantMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PendantMaker.build(id) local ok,e=PendantMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PendantMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PendantMaker.getQualityBonus() local b=0; for _,bd in ipairs(PendantMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PendantMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.bronzeCost and PendantMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.leatherCost and PendantMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PendantMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PendantMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PendantMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PendantMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PendantMaker.buildings==0 then return false,"Potrebna obesna delavnica" end; if not PendantMaker.maker then return false,"Potreben obeskar" end; return true end
function PendantMaker.make(pt,qty) qty=qty or 1; local ok,e=PendantMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.bronzeCost then PendantMaker.bronzeStock=PendantMaker.bronzeStock-d.bronzeCost*qty end; if d.leatherCost then PendantMaker.leatherStock=PendantMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PendantMaker.silverStock=PendantMaker.silverStock-d.silverCost*qty end; if d.goldCost then PendantMaker.goldStock=PendantMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PendantMaker.jewelStock=PendantMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PendantMaker.pearlStock=PendantMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PendantMaker.maker then t=math.max(1,t-math.floor(PendantMaker.maker.skill/13)) end; table.insert(PendantMaker.activeMaking,{id="pendant_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PendantMaker.completeMaking(m) local q=1.0+(PendantMaker.getQualityBonus()/100); if PendantMaker.maker then q=q+(PendantMaker.maker.skill/140) end; q=math.min(2.5,q); PendantMaker.productStock[m.productType]=(PendantMaker.productStock[m.productType] or 0)+m.quantity; PendantMaker.totalProducts=PendantMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PendantMaker.maker then PendantMaker.maker.itemsMade=PendantMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PendantMaker.maker.skill=math.min(100,PendantMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Obesek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pendant.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function PendantMaker.update(dt) if not _G.state then return end; PendantMaker.dayTimer=PendantMaker.dayTimer+dt; if PendantMaker.dayTimer>=30 then PendantMaker.dayTimer=0; for i=#PendantMaker.activeMaking,1,-1 do local m=PendantMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PendantMaker.completeMaking(m); table.remove(PendantMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PendantMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PendantMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PendantMaker.getStats() return {bronzeStock=PendantMaker.bronzeStock,leatherStock=PendantMaker.leatherStock,silverStock=PendantMaker.silverStock,goldStock=PendantMaker.goldStock,jewelStock=PendantMaker.jewelStock,pearlStock=PendantMaker.pearlStock,productStock=PendantMaker.productStock,numBuildings=#PendantMaker.buildings,hasMaker=PendantMaker.maker~=nil,makerName=PendantMaker.maker and PendantMaker.maker.name or "—",makerSkill=PendantMaker.maker and PendantMaker.maker.skill or 0,activeMaking=#PendantMaker.activeMaking,totalProducts=PendantMaker.totalProducts} end
return PendantMaker
